-- 20260708120000: F-VEHICLE-CAMINHONETE-CATALOG-AND-SPECS (Clayton 2026-07-08).
-- Popula o catálogo transversal de veículos com CAMINHONETES (dados reais de ficha técnica, CSV).
-- IDENTIDADE (marca→modelo→ano→versão) no catálogo governado que já existe (cascata de locação);
-- ESPECIFICAÇÃO (motor/potência/dimensões...) em vehicle_model_specs (facet governada, NÃO taxonomia).
-- Transversal: serve locação/venda/peças/rides/fretes. Forward-only, idempotente. Gerado do CSV.
BEGIN;
SELECT set_config('app.concept_governance', 'true', true);

-- concept 'caminhonete' já existe (mobilidade-e-logistica). Marcas:
INSERT INTO vehicle_makes (slug, name)
SELECT v.slug, v.name FROM (VALUES
  ('byd', 'BYD'),
  ('chevrolet', 'Chevrolet'),
  ('fiat', 'Fiat'),
  ('ford', 'Ford'),
  ('foton', 'Foton'),
  ('gwm', 'GWM'),
  ('jac', 'JAC'),
  ('mitsubishi', 'Mitsubishi'),
  ('nissan', 'Nissan'),
  ('ram', 'Ram'),
  ('toyota', 'Toyota'),
  ('volkswagen', 'Volkswagen')
) AS v(slug, name)
WHERE NOT EXISTS (SELECT 1 FROM vehicle_makes k WHERE k.slug = v.slug);

-- Modelos (concept=caminhonete). UNIQUE(make_id, concept_id, slug) — não colide com carro do mesmo make.
INSERT INTO vehicle_models (make_id, concept_id, slug, name)
