  ('volkswagen', 'kombi-pick-up-cabine-simples', 'Kombi Pick-up Cabine Simples'),
  ('volkswagen', 'saveiro', 'Saveiro')
) AS v(makeslug, mslug, mname)
JOIN vehicle_makes mk ON mk.slug = v.makeslug
JOIN concepts c ON c.slug = 'caminhonete'
WHERE NOT EXISTS (
  SELECT 1 FROM vehicle_models m WHERE m.make_id = mk.id AND m.concept_id = c.concept_id AND m.slug = v.mslug
);

