) AS v(makeslug, mslug, year)
JOIN vehicle_makes mk ON mk.slug = v.makeslug
JOIN concepts c ON c.slug = 'caminhonete'
JOIN vehicle_models m ON m.make_id = mk.id AND m.concept_id = c.concept_id AND m.slug = v.mslug
ON CONFLICT (model_id, year) DO NOTHING;

-- Ficha técnica (FACET governada — descreve, não identifica). Chave: modelo + ano + versão.
CREATE TABLE IF NOT EXISTS vehicle_model_specs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  model_id UUID NOT NULL REFERENCES vehicle_models(id) ON DELETE CASCADE,
  year INTEGER NOT NULL,
  version TEXT NOT NULL,
  motor TEXT, cilindrada_cc INTEGER, potencia_cv INTEGER, torque_kgfm NUMERIC,
  combustivel TEXT, tracao TEXT, cambio TEXT, num_portas INTEGER,
  capacidade_carga_kg INTEGER, peso_kg INTEGER,
  comprimento_cm INTEGER, largura_cm INTEGER, altura_cm INTEGER, entre_eixos_cm INTEGER,
  pneus TEXT, freios_diant TEXT, freios_tras TEXT,
  suspensao_diant TEXT, suspensao_tras TEXT, direcao TEXT,
  tanque_litros NUMERIC, cacamba_litros NUMERIC,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT uq_vehicle_model_spec UNIQUE (model_id, year, version)
);
CREATE INDEX IF NOT EXISTS idx_vms_model_year ON vehicle_model_specs (model_id, year);

